import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  b: ["barrel", { facing: "up" }],          // stores: sacks and barrels
  c: ["chest", { facing: "north" }],        // tool and ledger chests
