  ".............",
  ".............",
  "...L.....L...", // z=12: hanging lanterns on the centre line
  ".............",
  ".............",
  "...........L.", // z=15: hanging lantern over the foreman's bed
];

export function build(g) {
  return layers(g, [5, 6, 10], LEGEND, [FLOOR, STACK, LAMPS]);
}
EOF
